package com.mindcare.domain.certificate.service;
import com.mindcare.domain.certificate.repository.CertificateRepository; import java.math.BigDecimal; import java.time.Instant; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class CertificateService { private final CertificateRepository certificates; public Verification verify(String code){return certificates.findByCode(code).filter(c->c.isPubliclyVerifiable()).map(c->new Verification(true,c.getIssuedAt(),c.getHours(),c.getSessionCount(),c.getSupervisionCount())).orElse(new Verification(false,null,null,null,null));} public record Verification(boolean valid,Instant issuedAt,BigDecimal hours,Integer sessionCount,Integer supervisionCount){} }
